def read_tsv(path, fields):
    with path.open(encoding="utf-8", newline="") as stream:
        reader = csv.DictReader(stream, delimiter="\t")
        if tuple(reader.fieldnames or ()) != fields:
            raise ValueError(f"{path.name}: неожиданный заголовок TSV")
        rows = list(reader)
    if any(None in row or any(value is None for value in row.values()) for row in rows):
        raise ValueError(f"{path.name}: строка имеет неверное число столбцов")
    return rows


def norm(value):
    return " ".join(value.translate(NORMALIZATION).lower().split())


def main():
    added = read_tsv(ROOT / "4-added.tsv", ADDED_FIELDS)
    judges = read_tsv(ROOT / "5-judge-characteristics.tsv", JUDGE_FIELDS)
    if len(added) != 140:
        raise ValueError(f"4-added.tsv: ожидалось 140 строк, найдено {len(added)}")
    if len(judges) != 237:
        raise ValueError(f"5-judge-characteristics.tsv: ожидалось 237 строк, найдено {len(judges)}")
    if any(row["variant"] != "B" for row in added):
        raise ValueError("4-added.tsv: найдена строка вне варианта B")

    source_keys = [tuple(row[field] for field in ("moment", "variant", "map_number", "fact")) for row in added]
    decision_keys = {(row["moment"], row["map_number"]) for row in added}
    if len(set(source_keys)) != 140 or len(decision_keys) != 140:
        raise ValueError("4-added.tsv: исходные ключи не уникальны")
    if set(DECISIONS) != decision_keys or len(DECISIONS) != 140:
        raise ValueError("DECISIONS: ключи должны точно совпадать с 140 парами (moment, map_number)")

    for key, decision in DECISIONS.items():
        if not isinstance(decision, tuple) or len(decision) != 4:
            raise ValueError(f"DECISIONS {key!r}: ожидался кортеж (class, item, category, reason)")
        class_name, item, category, reason = decision
        item = str(item)
        if class_name not in CLASSES:
            raise ValueError(f"DECISIONS {key!r}: недопустимый класс {class_name!r}")
        if category not in CATEGORIES:
            raise ValueError(f"DECISIONS {key!r}: недопустимая категория {category!r}")
        if (class_name == "нужна характеристика мира" and item not in ITEMS) or (
            class_name != "нужна характеристика мира" and item != "—"
        ):
            raise ValueError(f"DECISIONS {key!r}: недопустимый пункт #894 {item!r}")
        if not isinstance(reason, str) or not reason.strip():
            raise ValueError(f"DECISIONS {key!r}: требуется непустое обоснование")

    output_rows = []
    marked = 0
    matched_judges = 0
    for row in added:
        key = (row["moment"], row["map_number"])
        quoted = re.fullmatch(r"«([^»]+)»\s+\([^)]*\)", row["fact"])
        fact = norm(quoted.group(1) if quoted else row["fact"])
        matches = []
        for judge in judges:
            quote = norm(judge["quote"])
            if judge["etalon"] == f"{row['moment']}-B" and fact and fact in quote:
                matches.append(
                    ",".join((
                        f"group={judge['group']}",
                        f"judge={judge['judge']}",
                        f"blind_id={judge['blind_id']}",
                        f"invention_index={judge['invention_index']}",
                        f"item={judge['item']}",
                    ))
                )
        if matches:
            marked += 1
            matched_judges += len(matches)
        class_name, item, category, reason = DECISIONS[key]
        output_rows.append({
            **row,
            "класс": class_name,
            "пункт #894": str(item),
            "отмечено судьями": " | ".join(matches) if matches else NO_MATCH,
            "категория §3.2": category,
            "обоснование": reason,
        })

    output_path = ROOT / "4-added-classes.tsv"
    fields = ADDED_FIELDS + NEW_FIELDS
    with output_path.open("w", encoding="utf-8", newline="") as stream:
        writer = csv.DictWriter(stream, fieldnames=fields, delimiter="\t", lineterminator="\n")
        writer.writeheader()
        writer.writerows(output_rows)

    readback = read_tsv(output_path, fields)
    if len(readback) != 140 or [tuple(row[field] for field in ADDED_FIELDS) for row in readback] != [
        tuple(row[field] for field in ADDED_FIELDS) for row in added
    ]:
        raise ValueError("4-added-classes.tsv: readback не сохранил 140 исходных строк и их порядок")

    class_counts = Counter(row["класс"] for row in readback)
    category_counts = Counter(row["категория §3.2"] for row in readback)
    print("Классы:")
    for value in CLASSES:
        print(f"{value}: {class_counts[value]}")
    print("Категории §3.2:")
    for value in CATEGORIES:
        print(f"{value}: {category_counts[value]}")
    print(f"Отмечено строк: {marked} из 140; совпавших записей судей: {matched_judges}")


if __name__ == "__main__":
    main()
